"""Relational data model. See docs/SCHEMA.md and docs/schema.sql (generated by `cli schema`)."""

from __future__ import annotations

from datetime import date, datetime, time, timezone

from sqlalchemy import (
    JSON,
    Boolean,
    Date,
    ForeignKey,
    Index,
    Integer,
    String,
    Text,
    Time,
    UniqueConstraint,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from .db import Base, UTCDateTime


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


# ------------------------------------------------------------------ vocabularies


class Service:
    MOVERS = "movers"
    TAKEOVERS = "takeovers"
    ALL = (MOVERS, TAKEOVERS)
    LABELS = {MOVERS: "Movers", TAKEOVERS: "Takeovers"}


class Step:
    J2 = "j2"  # 48 h before
    J1_FIRST = "j1_first"  # 24 h before
    J1_SECOND = "j1_second"  # 24 h before + 3 h
    MANUAL = "manual"
    AUTOMATIC = (J2, J1_FIRST, J1_SECOND)
    LABELS = {
        J2: "SMS à 48 h",
        J1_FIRST: "1er SMS à 24 h",
        J1_SECOND: "2e SMS à 24 h",
        MANUAL: "Relance manuelle",
    }


class AppointmentStatus:
    ACTIVE = "active"
    CANCELLED = "cancelled"


class Confirmation:
    TO_CONFIRM = "to_confirm"
    CONFIRMED = "confirmed"


class ConfirmationSource:
    TEAM = "team"  # internal checkbox: NOT a customer answer
    IMPORT = "import"  # "confirmed" column of an imported file
    CUSTOMER_REPLY = "customer_reply"  # reserved for a future, reliable integration


class JobStatus:
    SCHEDULED = "scheduled"  # waiting for its time
    RETRY_WAIT = "retry_wait"  # transient provider error, will retry before expiry
    BLOCKED = "blocked"  # configuration / data problem, re-checked until expiry
    SENDING = "sending"  # claimed by a worker
    SENT = "sent"  # accepted by the REAL provider
    SIMULATED = "simulated"  # simulation mode: nothing was sent
    FAILED = "failed"  # definitive provider failure
    CANCELLED = "cancelled"  # no longer relevant (confirmed, cancelled, suspended, modified)
    SKIPPED_LATE = "skipped_late"  # time already passed when scheduled: no retroactive send
    EXPIRED = "expired"  # could not be sent in its validity window
    UNCERTAIN = "uncertain"  # worker interrupted during the provider call: to verify, never resent

    PENDING = (SCHEDULED, RETRY_WAIT, BLOCKED)
    DELIVERED_TO_PROVIDER = (SENT, SIMULATED, UNCERTAIN)
    ERRORS = (FAILED, BLOCKED, UNCERTAIN, EXPIRED)


# ------------------------------------------------------------------ tables


class ImportBatch(Base):
    __tablename__ = "import_batch"

    id: Mapped[int] = mapped_column(primary_key=True)
    created_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow)
    created_by: Mapped[str] = mapped_column(String(80))
    filename: Mapped[str] = mapped_column(String(255))
    origin: Mapped[str] = mapped_column(String(40))  # csv | xlsx | crm (future)
    status: Mapped[str] = mapped_column(String(20), default="uploaded")  # uploaded | committed | discarded
    headers: Mapped[list] = mapped_column(JSON, default=list)
    # Raw rows are kept only until the import is committed or discarded (then purged).
    rows: Mapped[list | None] = mapped_column(JSON, nullable=True)
    mapping: Mapped[dict | None] = mapped_column(JSON, nullable=True)
    summary: Mapped[dict | None] = mapped_column(JSON, nullable=True)
    committed_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)


class Appointment(Base):
    __tablename__ = "appointment"

    id: Mapped[int] = mapped_column(primary_key=True)
    # Business identity: CRM appointment id when provided, else customer + service + local date/time.
    business_key: Mapped[str] = mapped_column(String(255), unique=True)
    external_ref: Mapped[str | None] = mapped_column(String(80), nullable=True)
    # Internal customer number (CRM). Never a phone number.
    customer_ref: Mapped[str] = mapped_column(String(80), index=True)
    first_name: Mapped[str] = mapped_column(String(120))
    last_name: Mapped[str] = mapped_column(String(120))
    phone_raw: Mapped[str] = mapped_column(String(40))
    phone_e164: Mapped[str | None] = mapped_column(String(20), nullable=True, index=True)
    phone_valid: Mapped[bool] = mapped_column(Boolean, default=False)

    appointment_date: Mapped[date] = mapped_column(Date)
    appointment_time: Mapped[time] = mapped_column(Time)
    timezone: Mapped[str] = mapped_column(String(40), default="Europe/Paris")
    appointment_at: Mapped[datetime] = mapped_column(UTCDateTime, index=True)
    service: Mapped[str | None] = mapped_column(String(20), nullable=True, index=True)

    status: Mapped[str] = mapped_column(String(20), default=AppointmentStatus.ACTIVE, index=True)
    cancellation_reason: Mapped[str | None] = mapped_column(String(255), nullable=True)
    cancelled_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)
    cancelled_by: Mapped[str | None] = mapped_column(String(80), nullable=True)

    confirmation: Mapped[str] = mapped_column(String(20), default=Confirmation.TO_CONFIRM, index=True)
    confirmed_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)
    confirmed_by: Mapped[str | None] = mapped_column(String(80), nullable=True)
    confirmation_source: Mapped[str | None] = mapped_column(String(20), nullable=True)

    suspended: Mapped[bool] = mapped_column(Boolean, default=False)
    suspension_reason: Mapped[str | None] = mapped_column(String(255), nullable=True)
    # Set when reminders were stopped (unconfirmed, un-suspended...) and a human must
    # explicitly validate which remaining steps are resumed.
    resume_pending: Mapped[bool] = mapped_column(Boolean, default=False)
    # Incremented when date / time / service change: older jobs belong to an outdated plan.
    schedule_revision: Mapped[int] = mapped_column(Integer, default=1)

    import_batch_id: Mapped[int | None] = mapped_column(
        ForeignKey("import_batch.id", ondelete="SET NULL"), nullable=True
    )
    import_origin: Mapped[str] = mapped_column(String(80), default="manual")
    imported_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow)
    created_by: Mapped[str] = mapped_column(String(80), default="system")
    updated_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow, onupdate=utcnow)
    last_action: Mapped[str | None] = mapped_column(String(255), nullable=True)
    last_action_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)

    jobs: Mapped[list[SmsJob]] = relationship(
        back_populates="appointment", cascade="all, delete-orphan", passive_deletes=True, order_by="SmsJob.id"
    )

    @property
    def full_name(self) -> str:
        return f"{self.first_name} {self.last_name}".strip()

    def job_for(self, step: str) -> SmsJob | None:
        """Job of the current plan (revision) for an automatic step."""
        for job in self.jobs:
            if job.step == step and job.revision == self.schedule_revision:
                return job
        return None


class TemplateSlot(Base):
    """One of the six slots (service x step). Content lives in immutable versions."""

    __tablename__ = "template_slot"
    __table_args__ = (UniqueConstraint("service", "step"),)

    id: Mapped[int] = mapped_column(primary_key=True)
    service: Mapped[str] = mapped_column(String(20))
    step: Mapped[str] = mapped_column(String(20))
    active_version_id: Mapped[int | None] = mapped_column(
        ForeignKey("template_version.id", use_alter=True, name="fk_slot_active_version"), nullable=True
    )

    versions: Mapped[list[TemplateVersion]] = relationship(
        foreign_keys="TemplateVersion.slot_id", back_populates="slot", order_by="TemplateVersion.version"
    )
    active_version: Mapped[TemplateVersion | None] = relationship(foreign_keys=[active_version_id], post_update=True)


class TemplateVersion(Base):
    """Immutable: editing a template always creates a new version."""

    __tablename__ = "template_version"
    __table_args__ = (UniqueConstraint("slot_id", "version"),)

    id: Mapped[int] = mapped_column(primary_key=True)
    slot_id: Mapped[int] = mapped_column(ForeignKey("template_slot.id"))
    version: Mapped[int] = mapped_column(Integer)
    body: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow)
    created_by: Mapped[str] = mapped_column(String(80))
    activated_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)
    activated_by: Mapped[str | None] = mapped_column(String(80), nullable=True)

    slot: Mapped[TemplateSlot] = relationship(foreign_keys=[slot_id], back_populates="versions")


class SmsJob(Base):
    """One planned SMS. ``dedup_key`` makes a step impossible to plan (hence send) twice."""

    __tablename__ = "sms_job"
    __table_args__ = (Index("ix_sms_job_due", "status", "next_attempt_at"),)

    id: Mapped[int] = mapped_column(primary_key=True)
    appointment_id: Mapped[int] = mapped_column(ForeignKey("appointment.id", ondelete="CASCADE"), index=True)
    revision: Mapped[int] = mapped_column(Integer)
    step: Mapped[str] = mapped_column(String(20))
    # Template slot used (= step for automatic jobs; chosen by the user for a manual reminder).
    template_step: Mapped[str] = mapped_column(String(20))
    dedup_key: Mapped[str] = mapped_column(String(120), unique=True)
    status: Mapped[str] = mapped_column(String(20), default=JobStatus.SCHEDULED, index=True)
    status_reason: Mapped[str | None] = mapped_column(String(255), nullable=True)

    scheduled_at: Mapped[datetime] = mapped_column(UTCDateTime)  # theoretical time
    next_attempt_at: Mapped[datetime] = mapped_column(UTCDateTime)  # next evaluation (retries)
    expires_at: Mapped[datetime] = mapped_column(UTCDateTime)  # never sent after this
    attempts: Mapped[int] = mapped_column(Integer, default=0)  # provider calls made

    claim_token: Mapped[str | None] = mapped_column(String(64), nullable=True)
    claimed_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)
    provider_call_started_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)

    sent_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)
    simulated: Mapped[bool] = mapped_column(Boolean, default=False)
    provider: Mapped[str | None] = mapped_column(String(40), nullable=True)
    provider_message_id: Mapped[str | None] = mapped_column(String(120), nullable=True, index=True)
    delivery_status: Mapped[str | None] = mapped_column(String(40), nullable=True)
    delivery_updated_at: Mapped[datetime | None] = mapped_column(UTCDateTime, nullable=True)

    template_version_id: Mapped[int | None] = mapped_column(ForeignKey("template_version.id"), nullable=True)
    sender: Mapped[str | None] = mapped_column(String(40), nullable=True)
    recipient: Mapped[str | None] = mapped_column(String(20), nullable=True)
    body: Mapped[str | None] = mapped_column(Text, nullable=True)
    segments: Mapped[int | None] = mapped_column(Integer, nullable=True)
    error_code: Mapped[str | None] = mapped_column(String(60), nullable=True)
    error_message: Mapped[str | None] = mapped_column(String(500), nullable=True)

    created_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow)
    created_by: Mapped[str] = mapped_column(String(80), default="system")
    updated_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow, onupdate=utcnow)

    appointment: Mapped[Appointment] = relationship(back_populates="jobs")
    template_version: Mapped[TemplateVersion | None] = relationship()


class ServiceConfig(Base):
    __tablename__ = "service_config"

    service: Mapped[str] = mapped_column(String(20), primary_key=True)
    # Sender configured by an administrator (phone number, alphanumeric sender ID or provider
    # messaging-service id). Empty = sending blocked for this service. Never defaulted.
    sender_id: Mapped[str | None] = mapped_column(String(40), nullable=True)
    enabled: Mapped[bool] = mapped_column(Boolean, default=True)
    updated_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow, onupdate=utcnow)
    updated_by: Mapped[str] = mapped_column(String(80), default="system")


class AppSetting(Base):
    __tablename__ = "app_setting"

    key: Mapped[str] = mapped_column(String(80), primary_key=True)
    value: Mapped[dict] = mapped_column(JSON)
    updated_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow, onupdate=utcnow)
    updated_by: Mapped[str] = mapped_column(String(80), default="system")


class BlockedNumber(Base):
    """Opt-outs and forbidden numbers: never texted, whatever the appointment."""

    __tablename__ = "blocked_number"

    id: Mapped[int] = mapped_column(primary_key=True)
    phone_e164: Mapped[str] = mapped_column(String(20), unique=True)
    reason: Mapped[str] = mapped_column(String(255))
    source: Mapped[str] = mapped_column(String(20))  # manual | opt_out | provider
    created_at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow)
    created_by: Mapped[str] = mapped_column(String(80))


class Event(Base):
    """History of every action. Appointment events are deleted with the appointment
    (retention / erasure); security audit events have ``appointment_id`` NULL and no PII."""

    __tablename__ = "event"

    id: Mapped[int] = mapped_column(primary_key=True)
    at: Mapped[datetime] = mapped_column(UTCDateTime, default=utcnow, index=True)
    actor: Mapped[str] = mapped_column(String(80))
    kind: Mapped[str] = mapped_column(String(60), index=True)
    appointment_id: Mapped[int | None] = mapped_column(
        ForeignKey("appointment.id", ondelete="CASCADE"), nullable=True, index=True
    )
    job_id: Mapped[int | None] = mapped_column(ForeignKey("sms_job.id", ondelete="CASCADE"), nullable=True)
    message: Mapped[str] = mapped_column(String(500))
    details: Mapped[dict | None] = mapped_column(JSON, nullable=True)
